/**
 * The mark fits itself to whatever box it is given. These run from Mastercard at 1.3:1 to
 * HDFC Bank at 5.8:1, so no single width or height suits all of them — `meet` scales each
 * to fit and centres it, which is what keeps a column of mixed wordmarks and badges
 * looking evenly weighted. The box is the caller's job; the CSS sets it.
 */
export function brandMark(slug) {
  const mark = brandMarks[slug];
  if (!mark) return '';
  return `<svg viewBox="${mark.viewBox}" width="100%" height="100%"
     preserveAspectRatio="xMidYMid meet" role="img"
     aria-label="${mark.title}">${mark.inner}</svg>`;
}
